package com.saleshub.service; import com.saleshub.domain.Customer; import java.math.*;
public class DiscountPolicy { public BigDecimal calculate(BigDecimal subtotal,int quantity,Customer customer,String coupon){ BigDecimal d=BigDecimal.ZERO; if(quantity>=10)d=d.add(subtotal.multiply(new BigDecimal(".15"))); else if(quantity>=5)d=d.add(subtotal.multiply(new BigDecimal(".10"))); else if(quantity>=3)d=d.add(subtotal.multiply(new BigDecimal(".05"))); if(customer!=null&&customer.isLoyal())d=d.add(subtotal.multiply(new BigDecimal(".05"))); if("BEMVINDO10".equalsIgnoreCase(coupon))d=d.add(subtotal.multiply(new BigDecimal(".10"))); return d.min(subtotal).setScale(2,RoundingMode.HALF_UP); } }
